#include <iostream>
#include <iomanip>
#include <cstdint>

// Trivially copyable struct representing a fixed-length record
struct AccountRecord {
    std::uint32_t accountNumber; // 4 bytes
    char lastName[15];           // 15 bytes
    char firstName[10];          // 10 bytes
    double balance;              // 8 bytes
};

int main() {
    constexpr std::size_t recordSize = sizeof(AccountRecord);
    std::cout << "Fixed record size: " << recordSize << " bytes\n\n";

    const std::uint32_t accountKeys[] = {1, 29, 37, 88, 100};

    std::cout << std::left << std::setw(12) << "Account Key"
              << std::setw(16) << "Start Offset"
              << "End Byte Offset\n";
    std::cout << std::string(45, '-') << "\n";

    for (std::uint32_t key : accountKeys) {
        std::uint64_t startOffset = static_cast<std::uint64_t>(key - 1) * recordSize;
        std::uint64_t endOffset = startOffset + recordSize - 1;
        std::cout << std::left << std::setw(12) << key
                  << std::setw(16) << startOffset
                  << endOffset << "\n";
    }

    return 0;
}

#include <iostream>
#include <sstream>
#include <cstring>
#include <cstdint>

// Trivially copyable POD struct suitable for binary raw I/O
struct ClientData {
    std::uint32_t acctNum; // account key (0 indicates unassigned slot)
    char lastName[15];     // fixed-length string
    char firstName[10];    // fixed-length string
    double balance;        // balance
};

int main() {
    // Simulate binary file on disk using a binary std::stringstream
    std::stringstream binaryStream(std::ios::in | std::ios::out | std::ios::binary);

    // Create blank client record with sentinel acctNum = 0
    ClientData blankClient{0, "", "", 0.0};
    constexpr std::size_t TOTAL_ACCOUNTS = 5; // scaled down for demonstration

    // Sequentially write blank records to pre-allocate file capacity
    for (std::size_t i = 1; i <= TOTAL_ACCOUNTS; ++i) {
        binaryStream.write(reinterpret_cast<const char*>(&blankClient), sizeof(ClientData));
    }

    // Determine total bytes written
    binaryStream.seekp(0, std::ios::end);
    std::streampos fileSize = binaryStream.tellp();

    std::cout << "Initialized " << TOTAL_ACCOUNTS << " blank records.\n";
    std::cout << "Record size: " << sizeof(ClientData) << " bytes.\n";
    std::cout << "Total file size: " << fileSize << " bytes.\n\n";

    // Inspect record slot 3 directly using calculated byte offset
    std::uint32_t targetSlot = 3;
    std::streamoff offset = static_cast<std::streamoff>((targetSlot - 1) * sizeof(ClientData));
    binaryStream.seekg(offset, std::ios::beg);

    ClientData readBack{};
    binaryStream.read(reinterpret_cast<char*>(&readBack), sizeof(ClientData));

    std::cout << "Slot " << targetSlot << " account number: " << readBack.acctNum 
              << " (" << (readBack.acctNum == 0 ? "vacant" : "occupied") << ")\n";

    return 0;
}
